import {DAYS,MODES,METHODS,schoolPlanFor,schoolDeparture,schoolSegments,schoolWarnings,feeRows,dueDate,initialView,uid,mins,clock,iso,localDate,addDays,monday,onDate,conflicts,autoPlan,validateState,emptyState,demoState,calendarICS} from './core.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={calendar:'M4 5h16v16H4z M7 3v4 M17 3v4 M4 10h16 M8 14h2 M14 14h2 M8 18h2',phone:'M6 3l4 4-2 3c2 3 3 4 6 6l3-2 4 4c-1 4-4 4-7 2C7 17 2 10 3 6z',settings:'M4 6h16 M4 12h16 M4 18h16 M8 3v6 M16 9v6 M10 15v6',car:'M4 11l2-6h12l2 6 M3 11h18v8H3z M6 19v2 M18 19v2 M6 14h2 M16 14h2',walk:'M13 3h.01 M12 7l-3 6 4 2 2 6 M9 13l-4 7 M12 8l4 4h4',pin:'M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0114 0z M15 10a3 3 0 11-6 0 3 3 0 016 0',spark:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',book:'M3 4h6l3 3 3-3h6v15h-6l-3 2-3-2H3z M12 7v14',clock:'M21 12a9 9 0 11-18 0 9 9 0 0118 0 M12 7v5l3 2',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',heart:'M12 21L3 12C-2 3 9 0 12 7c3-7 14-4 9 5z'};
const icon=n=>'<svg aria-hidden="true" viewBox="0 0 24 24"><path d="'+(icons[n]||icons.calendar)+'"/></svg>';
const hydrate=()=>document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));
function ask(message){return new Promise(resolve=>{const d=$('#confirmation');$('#confirm-message').textContent=message;const finish=value=>{d.close();resolve(value);};$('#confirm-yes').onclick=()=>finish(true);$('#confirm-no').onclick=()=>finish(false);d.oncancel=e=>{e.preventDefault();finish(false);};d.showModal();});}
const KEY='ieum-family-v1';let state,storageOK=true,corrupt=false,initialRaw=null;try{const raw=localStorage.getItem(KEY);initialRaw=raw;state=raw?validateState(JSON.parse(raw)):demoState();}catch{state=emptyState();storageOK=false;corrupt=true;}
const opening=initialView(state.prefs);let selected=opening.selected,week=monday(selected),child='all',view='schedule',layout=opening.layout,feeMonth=selected.slice(0,7),isDemo=!initialRaw&&!corrupt,editing=null,autoResult=null;let toastTimer;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4300);}
function save(){validateState(state);try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;isDemo=false;$('#save-status').textContent='이 기기에 저장됨';}catch{storageOK=false;$('#save-status').textContent='저장 실패 · 백업 필요';toast('기기에 저장하지 못했습니다. JSON 백업을 다운로드해 주세요.');}render();return storageOK;}
const childOf=id=>state.children.find(c=>c.id===id),contactOf=id=>state.contacts.find(c=>c.id===id),phone=p=>p.replace(/[^0-9+]/g,''),realPhone=p=>p&&!/0000-?0000/.test(p);
function contactLink(c,kind='tel'){return realPhone(c.phone)?'<a class="button small" href="'+kind+':'+esc(phone(c.phone))+'">'+icon(kind==='tel'?'phone':'arrow')+(kind==='tel'?'전화':'문자')+'</a>':'<button class="button small" data-action="contact" data-id="'+esc(c.id)+'">번호 등록</button>';}
function head(title,sub,buttons=''){return '<div class="page-heading"><div><h1>'+title+'</h1><p>'+sub+'</p></div><div class="heading-actions">'+buttons+'</div></div>';}
function render(){if(child!=='all'&&!childOf(child))child='all';$('#side-children').innerHTML=state.children.map(c=>'<div class="mini-child"><span class="avatar" style="--child-color:'+c.color+'">'+esc(c.name[0])+'</span><span>'+esc(c.name)+'<small>'+esc(c.grade)+'</small></span></div>').join('');document.querySelectorAll('.nav-item').forEach(e=>e.classList.toggle('active',e.dataset.view===view));$('#crumb').textContent={schedule:'시간표',contacts:'비상 연락망',manage:'가족 · 데이터 관리',school:'학교 · 방과후 · 돌봄'}[view];$('#main').innerHTML=(corrupt?'<div class="notice warn">저장된 데이터를 읽지 못했습니다. 기존 저장본을 덮어쓰지 않도록 백업 파일을 확인한 뒤 사용해 주세요.</div>':'')+(view==='schedule'?schedulePage():view==='contacts'?contactsPage():view==='school'?schoolHub():managePage());hydrate();updateClock();if(!storageOK)$('#save-status').textContent='저장 불가 · 백업 필요';}
function schedulePage(){const items=onDate(state,selected,child),pairs=conflicts(items),allWeek=Array.from({length:7},(_,i)=>onDate(state,addDays(week,i),child)).flat(),travel=items.reduce((n,s)=>n+s.travel,0);const d=localDate(selected);return head('우리 아이 하루를 잇다','배움부터 이동까지, 가족의 일정을 한눈에 확인하세요.','<button class="button" data-action="view" data-view="school">'+icon('book')+'학교 · 돌봄</button><button class="button" data-action="prefs">'+icon('settings')+'보기 설정</button><button class="button" data-action="ics">'+icon('download')+'캘린더 내보내기</button><button class="button primary" data-action="schedule">'+icon('plus')+'일정 추가</button>')+(isDemo?'<div class="demo-banner"><span>예시 가족의 시간표입니다. 우리 가족에 맞게 바꿔 보세요.</span><button data-action="fresh">빈 시간표로 시작</button></div>':'')+'<div class="stats"><div class="stat"><span class="stat-icon">'+icon('calendar')+'</span><div><small>선택한 날의 일정</small><strong>'+items.length+'<span>개의 배움</span></strong></div></div><div class="stat"><span class="stat-icon">'+icon('car')+'</span><div><small>예상 이동시간 합계</small><strong>'+travel+'<span>분 · 직접 입력 기준</span></strong></div></div><div class="stat"><span class="stat-icon">'+icon('shield')+'</span><div><small>일정 · 이동 겹침</small><strong>'+pairs.length+'<span>'+(pairs.length?'건 · 확인 필요':'건 · 여유로운 하루')+'</span></strong></div></div></div>'+schoolSummary(false)+'<div class="board-layout"><section class="card"><div class="board-top"><div class="section-row"><div class="period"><button class="icon-button" data-action="week" data-step="-1" aria-label="이전 주">‹</button><span>'+localDate(week).getFullYear()+'. '+(localDate(week).getMonth()+1)+'. '+localDate(week).getDate()+' - '+(localDate(addDays(week,6)).getMonth()+1)+'. '+localDate(addDays(week,6)).getDate()+'</span><button class="icon-button" data-action="week" data-step="1" aria-label="다음 주">›</button><button class="button small" data-action="today">오늘</button></div><div class="view-switch"><button data-action="layout" data-layout="day" class="'+(layout==='day'?'active':'')+'">하루</button><button data-action="layout" data-layout="week" class="'+(layout==='week'?'active':'')+'">주간</button></div></div><div class="chips"><button class="chip '+(child==='all'?'active':'')+'" data-action="filter" data-id="all">모든 자녀</button>'+state.children.map(c=>'<button class="chip '+(child===c.id?'active':'')+'" data-action="filter" data-id="'+c.id+'"><span class="dot" style="--child-color:'+c.color+'"></span>'+esc(c.name)+'</button>').join('')+'<button class="chip" data-action="child">+ 자녀</button></div><div class="day-tabs">'+Array.from({length:7},(_,i)=>{const date=addDays(week,i),dt=localDate(date),count=onDate(state,date,child).length;return '<button class="day-tab '+(date===selected?'selected ':'')+(date===iso(new Date())?'today':'')+'" data-action="day" data-date="'+date+'" aria-pressed="'+(date===selected)+'">'+DAYS[dt.getDay()]+'<strong>'+dt.getDate()+'</strong><span class="day-indicators">'+(count?'<i></i>'.repeat(Math.min(count,3)):'')+'</span></button>';}).join('')+'</div></div>'+timeChart()+(layout==='week'?weekBoard():'<div class="schedule-header"><b>'+ (d.getMonth()+1)+'월 '+d.getDate()+'일 '+DAYS[d.getDay()]+'요일</b><span class="legend">색상은 자녀 · 시간은 수업 기준</span></div><div class="timeline">'+(pairs.length?'<div class="notice warn">'+pairs.map(p=>esc(childOf(p[0].childId).name)+' · '+esc(p[0].title)+' ↔ '+esc(p[1].title)).join('<br>')+'<br>수업 또는 이동시간이 겹칩니다. 시간을 확인해 주세요.</div>':'')+(items.length?items.map(eventHTML).join(''):'<div class="empty">'+icon('calendar')+'<h3>여유로운 하루가 기다려요</h3><p>자녀의 배움과 이동을 하나씩 추가해 보세요.</p><button class="button primary" data-action="schedule">첫 일정 추가</button></div>')+'</div>')+'</section><aside class="right-column"><section class="auto-card"><div class="auto-mark">'+icon('spark')+'</div><h2>태권도 시간,<br>빈 시간에 쏙 넣어드릴게요.</h2><p>기존 수업과 이동시간을 살펴<br>겹치지 않는 반복 일정을 제안해요.<br>배치 후에도 자유롭게 수정하세요.</p><button class="button" data-action="auto">'+icon('spark')+'태권도 자동 배치</button></section><section class="card support-card"><div class="section-row"><h2>가까이 두는 연락처</h2><button class="text-button" data-action="view" data-view="contacts">전체 보기 ›</button></div>'+state.contacts.slice(0,2).map(c=>'<div class="contact-preview"><span class="avatar">'+icon('phone')+'</span><span><b>'+esc(c.name)+'</b><small>'+esc(c.role)+'</small></span>'+(realPhone(c.phone)?'<a class="icon-button" aria-label="'+esc(c.name)+' 전화" href="tel:'+phone(c.phone)+'">'+icon('phone')+'</a>':'<button class="icon-button" data-action="contact" data-id="'+c.id+'" aria-label="연락처 번호 등록">+</button>')+'</div>').join('')+(!state.contacts.length?'<p>보호자와 학원 연락처를 등록하세요.</p><button class="text-button" data-action="contact">+ 연락처 등록</button>':'')+'</section><section class="card support-card tips"><h2>'+icon('heart')+' 오늘도 안심하는 하루</h2><p>차량명과 탑승 장소를 메모해 두세요. 이동시간은 교통상황을 반영하지 않는 예상값입니다.</p></section></aside></div>'+feesSection()+infoSection();}
function eventHTML(s){const c=childOf(s.childId);return '<div class="schedule-line"><div class="schedule-time">'+s.start+'<small>'+s.end+' 종료</small></div><div class="event-wrap"><button class="event" style="--child-color:'+c.color+'" data-action="schedule" data-id="'+s.id+'" data-event-start="'+s.start+'" data-event-end="'+s.end+'"><div class="event-top"><h3>'+esc(s.title)+'</h3><span class="event-label">'+esc(c.name)+(s.date?' · 이 날짜만':'')+'</span></div><div class="event-meta"><span>'+icon('pin')+' '+esc(s.place||'장소 미지정')+'</span><span>'+icon('clock')+' '+(mins(s.end)-mins(s.start))+'분</span>'+(s.note?'<span title="'+esc(s.note)+'">메모 있음</span>':'')+'</div></button><div class="transport">'+(s.source==='school-plan'&&s.kind!=='school'?'교내 일정 · 별도 차량 이동 없음':icon(s.mode==='walk'?'walk':'car')+'<b>'+esc(MODES[s.mode])+'</b><span>'+clock(mins(s.start)-s.travel)+' 출발 · '+s.travel+'분 이동</span>'+(s.vehicle?'<span class="vehicle">'+esc(s.vehicle)+'</span>':''))+'</div></div></div>';}
function weekBoard(){return '<div class="week-mini">'+Array.from({length:7},(_,i)=>{const date=addDays(week,i),list=onDate(state,date,child);return '<div class="week-col"><h3>'+DAYS[localDate(date).getDay()]+' '+localDate(date).getDate()+'</h3>'+(conflicts(list).length?'<span class="muted">겹침 확인 필요</span>':'')+list.map(s=>'<button class="week-event" style="--child-color:'+childOf(s.childId).color+'" data-action="schedule" data-date="'+date+'" data-id="'+s.id+'">'+esc(s.title)+'<small>'+s.start+'–'+s.end+'<br>'+esc(childOf(s.childId).name)+' · '+esc(MODES[s.mode])+' '+s.travel+'분</small></button>').join('')+'</div>';}).join('')+'</div>';}
function infoSection(){return '<section class="info-section"><div class="info-heading"><h2>가족을 위한 작은 발견<span>우리 동네 교육 · 생활 정보</span></h2><button class="text-button" data-action="info">정보 · 광고 관리 ›</button></div><div class="info-grid">'+state.info.map(i=>'<'+(i.url?'a href="'+esc(i.url)+'" target="_blank" rel="noopener noreferrer"':'article')+' class="info-card"><div class="info-art">'+icon(i.sponsored?'spark':'book')+'</div><div><span class="eyebrow">'+(i.sponsored?'광고 · 협찬':'우리 동네 정보')+'</span><h3>'+esc(i.title)+'</h3><p>'+esc(i.body)+'</p></div>'+(i.url?'<span class="arrow">'+icon('arrow')+'</span>':'')+'</'+(i.url?'a':'article')+'>').join('')+'</div></section>';}
function contactsPage(){return head('필요한 순간, 바로 연결','저장한 연락처로 전화·문자 앱을 엽니다. 자동 신고나 메시지 발송은 하지 않습니다.','<button class="button primary" data-action="contact">'+icon('plus')+'연락처 추가</button>')+'<div class="notice">위급한 상황에는 대한민국 경찰 112 · 화재·구조·구급 119에 직접 연락하세요. 이 앱은 긴급 대응 기관이 아닙니다.</div>'+careContactsHTML()+'<div class="contacts-grid">'+state.contacts.map(c=>'<article class="card contact-card"><span class="avatar" style="--child-color:#547b65">'+icon('phone')+'</span><h2>'+esc(c.name)+'</h2><p>'+esc(c.role)+'</p><p class="phone-number">'+esc(c.phone)+'</p><div class="heading-actions">'+contactLink(c)+contactLink(c,'sms')+'<button class="button small" data-action="contact" data-id="'+c.id+'">편집</button></div></article>').join('')+'</div>'+(!state.contacts.length?'<div class="empty"><h3>아직 등록한 연락처가 없어요</h3><p>보호자, 학원, 차량 기사님의 연락처를 추가하세요.</p></div>':'');}
function managePage(){return head('우리 가족에 맞게','자녀 정보와 백업을 관리하세요. 저장한 정보는 다른 기기와 자동으로 공유되지 않습니다.')+'<div class="manage-grid"><section class="card"><h2>첫 화면 · 시간 눈금</h2><p>기본 보기: '+(state.prefs.startView==='day'?'하루':'일주일')+' · '+(state.prefs.focus==='today'?'오늘':DAYS[state.prefs.weekday]+'요일')+'<br>현재 시각 눈금: '+(state.prefs.showNow?'표시':'숨김')+'</p><button class="button" data-action="prefs">보기 설정 변경</button></section><section class="card"><h2>함께하는 자녀</h2>'+state.children.map(c=>'<div class="list-item"><span class="avatar" style="--child-color:'+c.color+'">'+esc(c.name[0])+'</span><span><strong>'+esc(c.name)+'</strong><small>'+esc(c.grade)+'</small></span><div class="buttons"><button class="button small" data-action="child" data-id="'+c.id+'">편집</button></div></div>').join('')+'<button class="text-button" data-action="child">+ 자녀 추가</button></section><section class="card"><h2>백업 · 캘린더</h2><p>브라우저 데이터 삭제나 기기 변경 전 백업하세요. JSON 파일에는 자녀 일정·학교생활·돌봄 연락처·학원비·납부 기록이 평문으로 담깁니다. 공개 저장소에 올리지 마세요.</p><div class="inline-buttons"><button class="button" data-action="backup">JSON 백업</button><button class="button" data-action="import">백업 불러오기</button><button class="button" data-action="ics">이번 주 ICS</button><button class="button" data-action="print">인쇄</button></div><input id="import-file" type="file" accept=".json,application/json" class="file-input"></section><section class="card"><h2>설치와 개인정보</h2><p>HTTPS로 배포하면 지원되는 브라우저에서 홈 화면에 추가할 수 있습니다. 앱을 한 번 연 뒤 기본 화면을 오프라인으로 사용할 수 있습니다. 전화·외부 정보 링크에는 연결이 필요합니다.</p><p>로그인, 가족 간 동기화, GPS 위치 확인, 푸시 알림, 실제 광고 송출은 포함되지 않습니다. 비상 연락은 기기의 전화·문자 기능을 사용합니다.</p></section><section class="card"><h2>데이터 초기화</h2><p>예시 일정을 다시 불러오거나, 모든 정보를 지우고 시작할 수 있습니다. 먼저 백업을 권장합니다.</p><div class="inline-buttons"><button class="button" data-action="demo">예시 불러오기</button><button class="button danger" data-action="fresh">모든 데이터 지우기</button></div></section></div>';}
function dialog(title,html){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=html;hydrate();if(!$('#editor').open)$('#editor').showModal();const f=$('#dialog-body form');if(f)f.addEventListener('submit',submitForm);}
function formWrap(type,body,existing=false){return '<form data-type="'+type+'">'+body+'<p class="form-error" role="alert"></p><div class="form-actions">'+(existing?'<button type="button" class="button danger" data-action="delete">삭제</button>':'')+'<button type="button" class="button" data-action="close">취소</button><button class="button primary" type="submit">저장</button></div></form>';}
const input=(name,label,value='',type='text',extra='')=>'<label>'+label+'<input name="'+name+'" type="'+type+'" value="'+esc(value)+'" '+extra+'></label>';
const options=(items,value)=>items.map(([v,t])=>'<option value="'+esc(v)+'" '+(String(value)===String(v)?'selected':'')+'>'+esc(t)+'</option>').join('');
const select=(name,label,items,value)=>'<label>'+label+'<select name="'+name+'">'+options(items,value)+'</select></label>';
const daysHTML=(days,name='days')=>'<div class="day-checks">'+[1,2,3,4,5,6,0].map(d=>'<label><input type="checkbox" name="'+name+'" value="'+d+'" '+(days.includes(d)?'checked':'')+'>'+DAYS[d]+'</label>').join('')+'</div>';
function editChild(id){editing={type:'child',id};const c=childOf(id)||{name:'',grade:'',color:'#7761b4'};dialog(id?'자녀 정보 수정':'우리 가족에 자녀 추가',formWrap('child',input('name','이름 또는 별명',c.name,'text','required maxlength="30"')+'<div class="form-grid">'+input('grade','학년 · 메모',c.grade,'text','maxlength="30"')+input('color','시간표 색상',c.color,'color')+'</div>',!!id));}
function editContact(id){editing={type:'contact',id};const c=contactOf(id)||{name:'',role:'',phone:''};dialog(id?'연락처 수정':'비상 연락처 추가',formWrap('contact',input('name','이름 · 기관명',c.name,'text','required maxlength="50"')+input('role','관계 · 담당 업무',c.role,'text','maxlength="50"')+input('phone','전화번호',c.phone,'tel','required maxlength="30"')+'<p class="help">본인 또는 동의받은 연락처만 입력하세요. 전화·문자는 버튼을 눌렀을 때 기기의 앱으로 연결됩니다.</p>',!!id));}
function editSchedule(id,date){const generated=onDate(state,date||selected).find(x=>x.id===id&&x.source==='school-plan');if(generated){if(date){selected=date;week=monday(date);feeMonth=date.slice(0,7);}editSchool(generated.childId,localDate(date||selected).getDay(),date||selected);return;}if(!state.children.length){toast('자녀를 먼저 추가해 주세요.');editChild();return;}if(date){selected=date;week=monday(date);}const s=state.schedules.find(x=>x.id===id)||{childId:child==='all'?state.children[0].id:child,title:'',kind:'academy',place:'',start:'14:00',end:'15:00',days:[localDate(selected).getDay()],date:'',mode:'walk',travel:10,vehicle:'',contactId:'',note:''};editing={type:'schedule',id};dialog(id?'일정과 이동 수정':'새로운 배움 추가',formWrap('schedule','<div class="form-grid">'+select('childId','자녀',state.children.map(c=>[c.id,c.name]),s.childId)+select('kind','일정 종류',[['school','학교'],['academy','학원'],['taekwondo','태권도'],['other','기타']],s.kind)+input('title','일정 이름',s.title,'text','required maxlength="60"')+input('place','장소 · 탑승 위치',s.place,'text','maxlength="120"')+input('start','수업 시작',s.start,'time','required')+input('end','수업 종료',s.end,'time','required')+'</div>'+select('scope','변경 범위',s.date?[['date','이 날짜만']]:[['repeat','매주 반복 일정'],['date','이 날짜만'+(id?' 변경':'')]],s.date?'date':'repeat')+'<div id="repeat-fields"><label>반복 요일</label>'+daysHTML(s.days)+'</div><div id="date-fields">'+input('date','적용 날짜',s.date||selected,'date','required')+'</div><div class="form-grid">'+select('mode','이 수업까지 이동수단',Object.entries(MODES),s.mode)+input('travel','이동시간 (분)',s.travel,'number','required min="0" max="180" step="1"')+input('vehicle','차량명 · 동행자',s.vehicle,'text','maxlength="80" placeholder="예: 태권도 2호차 / 엄마"')+select('contactId','연결할 연락처',[['','연결 안 함'],...state.contacts.map(c=>[c.id,c.name])],s.contactId)+'</div><label>메모<textarea name="note" maxlength="500">'+esc(s.note)+'</textarea></label><p class="help">이동시간은 해당 수업 직전에 배정됩니다. 자동 경로 계산·차량 위치 조회는 아닙니다. 반복 일정 변경은 과거 주에도 반영됩니다.</p>',!!id));toggleScope();const linked=contactOf(s.contactId);if(linked){const box=document.createElement('div');box.className='inline-buttons';box.innerHTML='<span class="help">연결된 연락처: '+esc(linked.name)+'</span>'+contactLink(linked)+contactLink(linked,'sms');$('#dialog-body form').prepend(box);}}
function toggleScope(){const s=$('[name=scope]');if(!s)return;$('#repeat-fields').hidden=s.value==='date';$('#date-fields').hidden=s.value!=='date';}
function editAuto(){if(!state.children.length){editChild();return;}editing={type:'auto'};autoResult=null;dialog('태권도, 빈 시간에 자동 배치','<form data-type="auto"><p class="help">도장의 실제 수업 가능 시간대를 입력하세요. 10분 간격으로 빈 시간을 찾아 제안합니다. 기존 태권도와 직접 편집한 일정은 유지합니다.</p>'+select('childId','배치할 자녀',state.children.map(c=>[c.id,c.name]),child==='all'?state.children[0].id:child)+'<label>수련 요일</label>'+daysHTML([1,2,3,4,5])+'<div class="form-grid">'+input('start','가능 시간 시작','14:00','time','required')+input('end','가능 시간 종료','19:00','time','required')+input('duration','한 번 수련시간 (분)',60,'number','required min="10" max="180" step="10"')+input('travel','도장까지 이동 (분)',15,'number','required min="0" max="180"')+input('place','도장 · 탑승 장소','이음 태권도','text','maxlength="120"')+select('mode','이동수단',Object.entries(MODES),'shuttle')+input('vehicle','차량명','','text','maxlength="80"')+select('contactId','도장 연락처',[['','연결 안 함'],...state.contacts.map(c=>[c.id,c.name])],'')+'</div><div class="notice neutral">반복 일정과 이미 등록된 같은 요일의 일회성 일정도 피해 배치합니다. 실제 도장 수업·차량 운행 여부는 별도로 확인하세요.</div><p class="form-error" role="alert"></p><div class="form-actions"><button type="button" class="button" data-action="close">취소</button><button class="button primary" type="submit">배치 미리보기</button></div></form>');}
function editInfo(id){const i=state.info.find(i=>i.id===id)||{title:'',body:'',url:'',sponsored:false};editing={type:'info',id};dialog('하단 정보 · 광고 카드', '<div class="inline-buttons" style="margin-bottom:20px">'+state.info.map(i=>'<button class="button small" data-action="info" data-id="'+i.id+'">'+esc(i.title)+'</button>').join('')+'<button class="button small" data-action="info">+ 새 카드</button></div>'+formWrap('info',input('title','카드 제목',i.title,'text','required maxlength="80"')+'<label>내용<textarea name="body" maxlength="500">'+esc(i.body)+'</textarea></label>'+input('url','정보 링크 (선택, https://...)',i.url,'url','maxlength="500"')+'<label class="check-label"><input type="checkbox" name="sponsored" '+(i.sponsored?'checked':'')+'>광고 · 협찬 콘텐츠로 표시</label><p class="help">카드는 이 기기에서만 편집됩니다. 실제 광고 네트워크나 추적 스크립트는 연결하지 않습니다.</p>',!!id));}
function emergency(){editing=null;dialog('필요한 순간, 바로 연락','<p class="help">대한민국 기준입니다. 아래 버튼은 기기의 전화 앱을 엽니다. 현재 위치나 자녀 정보가 자동 전송되지 않습니다.</p><div class="emergency-grid"><a href="tel:112">경찰 112<small>범죄 · 긴급 신고</small></a><a href="tel:119">구조·구급 119<small>화재 · 응급 상황</small></a></div>'+careContactsHTML(true)+state.contacts.map(c=>'<div class="list-item"><span><strong>'+esc(c.name)+'</strong><small>'+esc(c.phone)+'</small></span><div class="buttons">'+contactLink(c)+contactLink(c,'sms')+'</div></div>').join('')+'<button class="text-button" data-action="contact">+ 연락처 추가</button>');}
function submitForm(e){e.preventDefault();const form=e.target,f=new FormData(form),type=form.dataset.type,v=n=>String(f.get(n)||'').trim(),error=form.querySelector('.form-error');error.textContent='';try{if(type==='school'){submitSchool(form,f);return;}if(type==='auto'){const rules={days:f.getAll('days').map(Number),start:v('start'),end:v('end'),duration:Number(v('duration')),travel:Number(v('travel')),place:v('place'),mode:v('mode'),vehicle:v('vehicle'),contactId:v('contactId')};if(!rules.days.length)throw Error('수련 요일을 선택해 주세요.');if(mins(rules.start)+rules.duration>mins(rules.end))throw Error('가능 시간대보다 수련시간이 깁니다.');autoResult=autoPlan(state,v('childId'),rules);dialog('자동 배치 미리보기','<p class="help">'+esc(childOf(v('childId')).name)+'의 반복 시간표를 기준으로 찾았습니다. 도장 수업과 운행 가능 여부를 확인한 후 적용하세요.</p>'+autoResult.added.map(s=>'<div class="plan-row"><strong>'+DAYS[s.days[0]]+'요일</strong>'+s.start+'–'+s.end+' · '+esc(MODES[s.mode])+' '+s.travel+'분</div>').join('')+autoResult.skipped.map(s=>'<div class="plan-row muted"><strong>'+DAYS[s.day]+'요일</strong>'+esc(s.reason)+'</div>').join('')+'<div class="form-actions"><button class="button" data-action="auto">다시 설정</button>'+(autoResult.added.length?'<button class="button primary" data-action="apply-auto">'+autoResult.added.length+'개 일정 적용</button>':'<button class="button" data-action="close">닫기</button>')+'</div>');return;}
const next=structuredClone(state),id=editing?.id||uid();if(type==='prefs'){next.prefs={startView:v('startView'),focus:v('focus'),weekday:Number(v('weekday')),showNow:f.has('showNow')};}
if(type==='fee'){const item={id,childId:v('childId'),academy:v('academy'),amount:Number(v('amount')),dueDay:Number(v('dueDay')),method:v('method'),startMonth:v('startMonth'),endMonth:v('endMonth'),note:v('note')};next.fees=next.fees.filter(x=>x.id!==id).concat(item);}
if(type==='payment'){const plan=next.fees.find(x=>x.id===editing.feeId);if(!plan)throw Error('학원비 항목을 찾지 못했습니다.');const old=next.payments.find(x=>x.feeId===plan.id&&x.month===editing.month);next.payments=next.payments.filter(x=>!(x.feeId===plan.id&&x.month===editing.month));if(v('status')==='paid'){const row=feeRows(state,editing.month).find(x=>x.feeId===plan.id);next.payments.push({id:old?.id||uid(),feeId:plan.id,month:editing.month,paidDate:v('paidDate'),dueDate:row.dueDate,amount:Number(v('amount')),method:v('method'),academy:row.academy,childId:row.childId,note:v('note')});}}
if(type==='child'){const item={id,name:v('name'),grade:v('grade'),color:v('color')};next.children=next.children.filter(c=>c.id!==id).concat(item);}if(type==='contact'){const item={id,name:v('name'),role:v('role'),phone:v('phone')};next.contacts=next.contacts.filter(c=>c.id!==id).concat(item);}if(type==='info'){const item={id,title:v('title'),body:v('body'),url:v('url'),sponsored:f.has('sponsored')};next.info=next.info.filter(i=>i.id!==id).concat(item);}if(type==='schedule'){const original=state.schedules.find(s=>s.id===id),once=v('scope')==='date';const item={id,childId:v('childId'),title:v('title'),place:v('place'),kind:v('kind'),start:v('start'),end:v('end'),mode:v('mode'),travel:Number(v('travel')),vehicle:v('vehicle'),contactId:v('contactId'),note:v('note'),days:once?[]:f.getAll('days').map(Number),date:once?v('date'):'',exclusions:original?.exclusions||[]};if(!once&&!item.days.length)throw Error('반복 요일을 하나 이상 선택하세요.');if(mins(item.start)>=mins(item.end))throw Error('종료 시간은 시작 시간보다 늦어야 합니다.');if(mins(item.start)<item.travel)throw Error('출발 시간이 전날이 되지 않도록 이동시간을 줄여 주세요.');if(original&&!original.date&&once){if(item.date!==selected)throw Error('이 날짜만 변경할 때에는 선택한 '+selected+'을 유지하세요. 다른 날짜는 새 일정으로 추가하세요.');next.schedules.find(s=>s.id===id).exclusions=[...new Set([...original.exclusions,selected])];item.id=uid();item.exclusions=[];next.schedules.push(item);}else next.schedules=next.schedules.filter(s=>s.id!==id).concat(item);}
validateState(next);state=next;if(type==='prefs'){const start=initialView(state.prefs);selected=start.selected;layout=start.layout;week=monday(selected);feeMonth=selected.slice(0,7);}corrupt=false;const persisted=save();$('#editor').close();toast((persisted?'저장했습니다.':'저장되지 않았습니다. JSON 백업이 필요합니다.')+(type==='schedule'&&conflicts(onDate(state,selected,child)).length?' 선택한 날의 일정·이동 겹침을 확인하세요.':''));}catch(err){error.textContent=err.message;}}
async function deleteItem(){if(editing?.type==='school'){await deleteSchool();return;}if(!editing?.id)return;const {type,id}=editing;const s=state.schedules.find(s=>s.id===id),scope=$('[name=scope]')?.value;if(!await ask(type==='child'?'자녀와 이 자녀의 모든 일정·학원비·납부 기록을 삭제할까요?':type==='fee'?'이 학원비와 연결된 모든 납부 기록을 삭제할까요? 기록을 남기려면 대신 종료 월을 설정하세요.':type==='schedule'&&scope==='date'&&!s.date?'선택한 날짜의 일정만 제외할까요?':'이 항목을 삭제할까요?'))return;if(type==='child'){state.children=state.children.filter(c=>c.id!==id);state.schedules=state.schedules.filter(s=>s.childId!==id);state.schoolPlans=state.schoolPlans.filter(p=>p.childId!==id);const removed=state.fees.filter(f=>f.childId===id).map(f=>f.id);state.fees=state.fees.filter(f=>f.childId!==id);state.payments=state.payments.filter(p=>p.childId!==id&&!removed.includes(p.feeId));}if(type==='contact'){state.contacts=state.contacts.filter(c=>c.id!==id);state.schoolPlans.forEach(p=>{if(p.pickup.contactId===id)p.pickup.contactId='';});state.schedules.forEach(s=>{if(s.contactId===id)s.contactId='';});}if(type==='fee'){state.fees=state.fees.filter(f=>f.id!==id);state.payments=state.payments.filter(p=>p.feeId!==id);}if(type==='info')state.info=state.info.filter(i=>i.id!==id);if(type==='schedule'){if(scope==='date'&&!s.date)s.exclusions=[...new Set([...s.exclusions,selected])];else state.schedules=state.schedules.filter(s=>s.id!==id);}save();$('#editor').close();toast('삭제했습니다.');}
function download(data,name,mime){const url=URL.createObjectURL(new Blob([data],{type:mime})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
async function importFile(file){if(!file)return;try{if(file.size>5*1024*1024)throw Error('5MB 이하의 백업 파일을 선택해 주세요.');const imported=validateState(JSON.parse(await file.text()));if(!await ask('현재 가족 정보를 백업 파일의 '+imported.children.length+'명 · '+imported.schedules.length+'개 일정으로 바꿀까요? 기존 정보가 교체됩니다.'))return;state=imported;corrupt=false;const persisted=save();toast(persisted?'백업을 불러왔습니다.':'백업은 열었지만 기기 저장에 실패했습니다. 원본 파일을 보관하세요.');}catch(e){toast('불러오기 실패: '+e.message);}}
document.addEventListener('change',e=>{if(['schoolScope','schoolEnabled','careEnabled'].includes(e.target.name))toggleSchoolFields();if(e.target.name==='scope')toggleScope();if(e.target.id==='import-file')importFile(e.target.files[0]);});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;if(a==='view'){view=b.dataset.view;render();}if(a==='school')editSchool(b.dataset.child?b.dataset.child:(child==='all'?state.children[0]?.id:child),b.dataset.day?Number(b.dataset.day):localDate(selected).getDay(),b.dataset.date||selected);if(a==='af-add'){const list=$('#after-rows');list.insertAdjacentHTML('beforeend',afterRow({id:uid(),title:'',start:'14:00',end:'15:00',place:'',teacher:'',phone:''}));}if(a==='af-remove')b.closest('[data-af-row]').remove();if(a==='filter'){child=id;render();}if(a==='day'){selected=b.dataset.date;layout='day';feeMonth=selected.slice(0,7);render();}if(a==='week'){week=addDays(week,Number(b.dataset.step)*7);selected=addDays(selected,Number(b.dataset.step)*7);feeMonth=selected.slice(0,7);render();}if(a==='today'){selected=iso(new Date());week=monday(selected);feeMonth=selected.slice(0,7);layout='day';render();}if(a==='layout'){layout=b.dataset.layout;render();}if(a==='fee-list')feeList();if(a==='prefs')editPrefs();if(a==='fee')editFee(id);if(a==='payment')editPayment(id);if(a==='fee-month'){feeMonth=shiftMonth(feeMonth,Number(b.dataset.step));render();}if(a==='child')editChild(id);if(a==='contact')editContact(id);if(a==='schedule')editSchedule(id,b.dataset.date);if(a==='info')editInfo(id);if(a==='emergency')emergency();if(a==='auto')editAuto();if(a==='apply-auto'&&autoResult){state.schedules.push(...autoResult.added);const n=autoResult.added.length;autoResult=null;const persisted=save();$('#editor').close();toast(persisted?n+'개의 태권도 일정을 배치했습니다.':'일정을 배치했지만 저장에 실패했습니다. JSON 백업을 다운로드하세요.');}if(a==='delete')deleteItem();if(a==='close')$('#editor').close();if(a==='backup'&&await ask('자녀 일정·학교생활·돌봄 연락처·학원비·납부 기록이 포함된 평문 파일을 저장합니다. 안전한 곳에 보관하고 공개하지 마세요.'))download(JSON.stringify(state,null,2),'ieum-backup-'+iso(new Date())+'.json','application/json');if(a==='import')$('#import-file').click();if(a==='ics'){if(await ask('선택한 주의 '+(child==='all'?'모든 자녀':childOf(child).name)+' 일정을 캘린더 파일로 내보냅니다. 학교·방과후·돌봄 일정과 장소·메모도 포함됩니다. 전화번호 필드는 제외되지만 메모에 적은 내용은 포함됩니다. 계속할까요?'))download(calendarICS(state,week,child),'ieum-week-'+week+'.ics','text/calendar;charset=utf-8');}if(a==='print')window.print();if(a==='fresh'&&await ask('기존 자녀·일정·연락처·학원비·납부 기록을 모두 삭제하고 빈 시간표로 시작할까요?')){state=emptyState();corrupt=false;save();toast('빈 시간표로 시작합니다. 자녀를 추가해 주세요.');}if(a==='demo'&&await ask('현재 정보를 지우고 예시 시간표로 교체할까요?')){state=demoState();corrupt=false;save();toast('예시 시간표를 불러왔습니다.');}});

function shiftMonth(m,offset){const d=localDate(m+'-01');d.setMonth(d.getMonth()+offset);return iso(d).slice(0,7);}
const won=n=>new Intl.NumberFormat('ko-KR').format(n)+'원';
function editPrefs(){editing={type:'prefs'};const p=state.prefs;dialog('첫 화면과 시간 눈금 설정',formWrap('prefs',select('startView','앱을 열 때 기본 보기',[['day','하루 시간표'],['week','일주일 전체']],p.startView)+select('focus','기본으로 보여줄 날짜',[['today','오늘 요일 자동 선택'],['weekday','지정한 요일 우선 표시']],p.focus)+select('weekday','지정 요일 (이번 주 기준)',[1,2,3,4,5,6,0].map(d=>[d,DAYS[d]+'요일']),p.weekday)+'<label class="check-label"><input type="checkbox" name="showNow" '+(p.showNow?'checked':'')+'>현재 시각 눈금 표시</label><p class="help">요일은 월~일로 묶인 이번 주 기준입니다. 화면의 하루 / 주간 버튼으로 언제든 전환할 수 있습니다. 설정은 이 브라우저에 저장되며 현재 시각은 기기 시계 기준입니다.</p>'));}
function timeChart(){const today=iso(new Date()),list=onDate(state,selected,child),kids=state.children.filter(c=>child==='all'||c.id===child);return '<section class="time-chart" aria-label="하루 시간 눈금"><div class="time-chart-title"><b>'+icon('clock')+' 하루 시간 눈금</b><span class="live-clock" data-live-clock></span></div><p class="time-chart-help">'+(selected===today?'오늘 일정 위에 현재 시각을 표시합니다.':'선택한 날짜 '+selected+' · 현재 시각 선은 오늘 날짜에서만 표시됩니다.')+'</p><div class="time-plot"><div class="time-axis"><span>00</span><span>06</span><span>12</span><span>18</span><span>24시</span></div>'+kids.map(c=>'<div class="time-track-row"><span class="track-name">'+esc(c.name)+'</span><div class="time-track">'+list.filter(s=>s.childId===c.id).map(s=>'<button class="time-block travel-block" style="left:'+((mins(s.start)-s.travel)/14.4)+'%;width:'+(s.travel/14.4)+'%;--child-color:'+c.color+'" data-action="schedule" data-id="'+s.id+'" title="'+esc(c.name+' · '+MODES[s.mode]+' '+s.travel+'분 이동')+'" aria-label="'+esc(c.name+' '+s.title+' 이동 '+s.travel+'분')+'"></button><button class="time-block" style="left:'+(mins(s.start)/14.4)+'%;width:'+((mins(s.end)-mins(s.start))/14.4)+'%;--child-color:'+c.color+'" data-action="schedule" data-id="'+s.id+'" title="'+esc(s.title+' '+s.start+'–'+s.end)+'" aria-label="'+esc(c.name+' '+s.title+' '+s.start+'부터 '+s.end)+'">'+esc(s.title)+'</button>').join('')+'</div></div>').join('')+'<div class="now-layer" data-now-layer><i class="now-tick" data-now-tick><span data-now-label></span></i></div></div><div class="time-chart-legend"><i></i>수업 <i class="travel-swatch"></i>이동 <span>상세 시간은 아래 일정에서 확인</span></div></section>';}
function updateClock(){const now=new Date(),today=iso(now),value=clock(now.getHours()*60+now.getMinutes());document.querySelectorAll('[data-live-clock]').forEach(e=>e.textContent='현재 '+value);const layer=$('[data-now-layer]');if(layer){layer.hidden=!state.prefs.showNow||selected!==today;const tick=$('[data-now-tick]');tick.style.left=((now.getHours()*60+now.getMinutes())/14.4)+'%';$('[data-now-label]').textContent=value;tick.style.setProperty('--label-shift',now.getHours()>=22?'-100%':now.getHours()<2?'0%':'-50%');}document.querySelectorAll('[data-event-start]').forEach(e=>e.classList.toggle('in-progress',selected===today&&value>=e.dataset.eventStart&&value<e.dataset.eventEnd));}
function feesSection(){const rows=feeRows(state,feeMonth,child),total=rows.reduce((a,r)=>a+r.amount,0),paid=rows.filter(r=>r.paid).reduce((a,r)=>a+r.amount,0),today=iso(new Date());let last='';return '<section class="fees-section card"><div class="fees-heading"><div><span class="eyebrow">TUITION PLANNER</span><h2>학원비, 빠뜨리지 않도록</h2><p>납부 예정과 실제 완료를 구분해 기록하세요.</p></div><button class="button primary" data-action="fee">'+icon('plus')+'학원비 등록</button></div><div class="fees-toolbar"><div class="period"><button class="icon-button" data-action="fee-month" data-step="-1" aria-label="이전 납부 월">‹</button><b>'+feeMonth.replace('-','년 ')+'월</b><button class="icon-button" data-action="fee-month" data-step="1" aria-label="다음 납부 월">›</button></div><span class="muted">'+(child==='all'?'모든 자녀':esc(childOf(child).name))+' · '+rows.length+'건</span></div><div class="fees-summary"><span>이번 달 합계<strong>'+won(total)+'</strong></span><span>납부 완료<strong>'+won(paid)+'</strong></span><span>미납부 예정액<strong>'+won(total-paid)+'</strong></span></div><div class="fee-list">'+(rows.length?rows.map(r=>{const dateHeader=r.dueDate!==last?'<div class="fee-date">'+Number(r.dueDate.slice(5,7))+'월 '+Number(r.dueDate.slice(8))+'일 <span>'+DAYS[localDate(r.dueDate).getDay()]+'요일</span></div>':'';last=r.dueDate;const status=r.paid?'납부 완료':r.dueDate<today?'기한 지남':r.method==='auto'?'자동납부 예정':'납부 예정';return dateHeader+'<article class="fee-row"><span class="avatar" style="--child-color:'+childOf(r.childId).color+'">'+esc(childOf(r.childId).name[0])+'</span><div class="fee-name"><strong>'+esc(r.academy)+'</strong><small>'+esc(childOf(r.childId).name)+' · '+esc(METHODS[r.method])+(r.paid?' · '+r.payment.paidDate+' 납부':'')+'</small></div><div class="fee-amount"><strong>'+won(r.amount)+'</strong><span class="fee-status '+(r.paid?'paid':r.dueDate<today?'overdue':r.method==='auto'?'automatic':'')+'">'+status+'</span></div><div class="fee-actions"><button class="button small" data-action="payment" data-id="'+r.feeId+'">'+(r.paid?'납부 기록 수정':'납부 확인')+'</button><button class="text-button" data-action="fee" data-id="'+r.feeId+'">회비 설정</button></div></article>';}).join(''):'<div class="empty"><h3>등록된 학원비가 없어요</h3><p>매월 납부일, 금액, 자동납부·카드·송금 방식을 등록해 보세요.<br>등록된 다른 달 항목은 회비 설정 목록에서 편집할 수 있어요.</p></div>')+'</div><div class="fees-foot"><button class="text-button" data-action="fee-list">전체 회비 설정 목록</button><span>자동 결제·계좌 조회 기능이 아닙니다. 실제 납부는 직접 확인하세요.</span></div></section>';}
function editFee(id){if(!state.children.length){toast('자녀를 먼저 추가해 주세요.');editChild();return;}const f=state.fees.find(x=>x.id===id)||{childId:child==='all'?state.children[0].id:child,academy:'',amount:'',dueDay:5,method:'auto',startMonth:feeMonth,endMonth:'',note:''};editing={type:'fee',id};dialog(id?'학원비 반복 설정 수정':'학원비 납부일 등록',formWrap('fee','<div class="form-grid">'+select('childId','자녀',state.children.map(c=>[c.id,c.name]),f.childId)+input('academy','학원 · 회비 이름',f.academy,'text','required maxlength="80"')+input('amount','매월 예정 금액 (원)',f.amount,'number','required min="0" max="100000000" step="1"')+input('dueDay','매월 납부일 (1~31일)',f.dueDay,'number','required min="1" max="31" step="1"')+select('method','기본 납부 방식',Object.entries(METHODS),f.method)+input('startMonth','시작 월',f.startMonth,'month','required')+input('endMonth','종료 월 (선택)',f.endMonth,'month')+'</div><label>메모<textarea name="note" maxlength="500">'+esc(f.note)+'</textarea></label><p class="help">해당 일자가 없는 달은 말일로 표시합니다. 자동납부도 직접 완료 확인해야 합니다. 반복 설정을 바꿔도 이미 완료한 기록의 금액·방식·납부일은 유지합니다. 수강 종료 시 종료 월을 지정하세요.</p>',!!id));}
function editPayment(id){const r=feeRows(state,feeMonth).find(x=>x.feeId===id);if(!r){toast('이 달에 해당하는 회비가 없습니다.');return;}editing={type:'payment',feeId:id,month:feeMonth};dialog('납부 확인 · '+r.academy,formWrap('payment','<div class="notice neutral">'+esc(childOf(r.childId).name)+' · '+feeMonth+' 회비 · 예정일 '+r.dueDate+'<br>완료 기록은 실제 결제를 대신하지 않습니다.</div>'+select('status','납부 상태',[['pending','아직 납부 전 / 완료 취소'],['paid','실제 납부 완료']],'paid')+'<div class="form-grid">'+input('paidDate','실제 납부일',r.payment?.paidDate||iso(new Date()),'date','required')+input('amount','실제 납부 금액 (원)',r.amount,'number','required min="0" max="100000000" step="1"')+select('method','실제 납부 방식',Object.entries(METHODS),r.method)+'</div><label>납부 메모<textarea name="note" maxlength="500">'+esc(r.payment?.note||'')+'</textarea></label><p class="help">카드번호·계좌 비밀번호는 입력하지 마세요. 완료 취소는 해당 월의 기록만 지우고 반복 예정 항목은 유지합니다.</p>'));}
function feeList(){editing=null;dialog('전체 회비 설정 목록',state.fees.map(f=>'<div class="list-item"><span><strong>'+esc(f.academy)+'</strong><small>'+esc(childOf(f.childId).name)+' · 매월 '+f.dueDay+'일 · '+won(f.amount)+'<br>'+f.startMonth+' ~ '+(f.endMonth||'계속')+'</small></span><div class="buttons"><button class="button small" data-action="fee" data-id="'+f.id+'">편집</button></div></div>').join('')+'<button class="text-button" data-action="fee">+ 새 학원비 등록</button>');}


function defaultSchool(childId,day){const old=state.schedules.find(s=>s.childId===childId&&s.kind==='school'&&!s.date&&s.days.includes(day));return {id:uid(),childId,day,date:'',enabled:true,school:old?.place||'',regularStart:old?.start||'09:00',regularEnd:old?.end||'13:00',schoolTravel:old?.travel??10,schoolMode:old?.mode||'walk',after:[],care:{enabled:false,start:old?.end||'13:00',end:'16:00',teacher:'',room:'',phone:'',teacherPhone:'',note:''},pickup:{mode:'walk',vehicle:'',place:'',contactId:''},note:''};}
function schoolCall(number,label='교실 전화'){if(!realPhone(number))return '<span class="help">예시 번호 · 실제 연락처로 수정</span>';return '<a class="button small school-call" href="tel:'+esc(phone(number))+'">'+icon('phone')+esc(label)+'</a>';}
function schoolSummary(full){const kids=state.children.filter(c=>child==='all'||c.id===child);if(!kids.length)return '';return '<section class="school-summary" aria-label="학교 출발 및 돌봄 안내"><div class="info-heading"><h2>학교에서 나오는 시간 <span>'+selected+' · 계획 기준, 실제 퇴실 확인 아님</span></h2>'+(!full?'<button class="text-button" data-action="view" data-view="school">요일별 학교생활 설정 ›</button>':'')+'</div><div class="school-cards">'+kids.map(c=>{const p=schoolPlanFor(state,c.id,selected),day=localDate(selected).getDay(),btn='<button class="button small" data-action="school" data-child="'+c.id+'" data-day="'+day+'" data-date="'+selected+'">'+(p?'설정 수정':'학교생활 설정')+'</button>';if(!p)return '<article class="school-day-card"><div class="section-row"><strong>'+esc(c.name)+'</strong>'+btn+'</div><p class="help">요일마다 다른 정규수업·방과후·돌봄 시간을 설정하세요. 설정 전에는 기존 학교 일정이 유지됩니다.</p></article>';if(!p.enabled)return '<article class="school-day-card"><div class="section-row"><strong>'+esc(c.name)+' · 등교하지 않는 날</strong>'+btn+'</div><p class="help">'+(p.date?'이 날짜만 적용':'매주 '+DAYS[day]+'요일')+' · 학원 일정은 그대로 유지됩니다.</p></article>';const warnings=schoolWarnings(state,selected,c.id),segments=schoolSegments(p),care=p.care;return '<article class="school-day-card"><div class="section-row"><div><span class="eyebrow">'+esc(c.name)+' · '+esc(p.school)+(p.date?' · 날짜 예외':'')+'</span><div class="school-release"><b>'+schoolDeparture(p)+'</b><span>학교 출발 가능</span></div></div>'+btn+'</div><div class="school-chain"><span>정규 '+p.regularEnd+' 종료</span>'+p.after.map(a=>'<span>방과후 '+esc(a.title)+' '+a.end+'</span>').join('')+(care.enabled?'<span class="care-chip">돌봄 '+care.end+' 퇴실</span>':'')+'</div>'+(full?'<div class="school-segments">'+segments.map(s=>'<div><b>'+s.start+'–'+s.end+'</b><span>'+esc(s.title)+(s.kind==='care'?' · '+esc(care.room):'')+'</span></div>').join('')+'</div>':'')+(care.enabled?'<div class="care-contact"><div><b>'+esc(care.teacher)+' 선생님</b><small>'+esc(care.room)+' · '+esc(care.phone)+'</small></div>'+schoolCall(care.phone)+(care.teacherPhone?schoolCall(care.teacherPhone,'업무 전화'):'')+'</div>':'')+'<p class="school-pickup">학교 출발: '+esc(MODES[p.pickup.mode])+(p.pickup.vehicle?' · '+esc(p.pickup.vehicle):'')+(p.pickup.place?' · '+esc(p.pickup.place):'')+'</p>'+(warnings.length?'<div class="notice warn">'+warnings.map(esc).join('<br>')+'</div>':'')+'</article>';}).join('')+'</div></section>';}
function schoolHub(){const kids=state.children.filter(c=>child==='all'||c.id===child);return head('학교 · 방과후 · 돌봄','정규수업 종료부터 실제 학교 출발까지, 자녀별·요일별로 연결하세요.','<button class="button primary" data-action="school">'+icon('plus')+'학교생활 설정</button>')+'<div class="notice neutral">돌봄 이용 시 선생님 이름 · 교실명 · 교실 전화번호는 필수입니다. 업무 연락처는 추가로 기록할 수 있습니다. 기존 학교 일정은 삭제하지 않으며, 설정한 날짜·요일에만 새 학교생활 계획이 대신 표시됩니다.</div><section class="card school-week-card"><div class="section-row"><div class="period"><button class="icon-button" data-action="week" data-step="-1" aria-label="이전 학교 주">‹</button><b>'+week+' 주간</b><button class="icon-button" data-action="week" data-step="1" aria-label="다음 학교 주">›</button><button class="button small" data-action="today">오늘</button></div></div><div class="chips"><button class="chip '+(child==='all'?'active':'')+'" data-action="filter" data-id="all">모든 자녀</button>'+state.children.map(c=>'<button class="chip '+(child===c.id?'active':'')+'" data-action="filter" data-id="'+c.id+'">'+esc(c.name)+'</button>').join('')+'</div><div class="day-tabs">'+Array.from({length:7},(_,i)=>{const date=addDays(week,i);return '<button class="day-tab '+(date===selected?'selected':'')+'" data-action="day" data-date="'+date+'">'+DAYS[localDate(date).getDay()]+'<strong>'+localDate(date).getDate()+'</strong></button>';}).join('')+'</div><div class="school-week-list">'+kids.map(c=>'<div class="school-child-week"><h2>'+esc(c.name)+'의 요일별 학교 출발</h2><div class="school-week-grid">'+Array.from({length:5},(_,i)=>{const date=addDays(week,i),p=schoolPlanFor(state,c.id,date);return '<button class="school-week-day '+(date===selected?'chosen':'')+'" data-action="school" data-child="'+c.id+'" data-day="'+(i+1)+'" data-date="'+date+'"><b>'+DAYS[i+1]+'요일</b><strong>'+(p?(p.enabled?schoolDeparture(p):'휴업'):'미설정')+'</strong><small>'+(p?.enabled?'정규 '+p.regularEnd+'<br>방과후 '+p.after.length+'개 · '+(p.care.enabled?'돌봄 '+p.care.end:'돌봄 없음'):p?'등교하지 않음':'눌러서 설정')+'</small>'+(p?.date?'<span>이 날짜 예외</span>':'')+'</button>';}).join('')+'</div></div>').join('')+'</div></section>'+schoolSummary(true);}
function careContactsHTML(useToday=false){const contactDate=useToday?iso(new Date()):selected;const map=new Map();for(const c of state.children){const plans=[schoolPlanFor(state,c.id,contactDate),...state.schoolPlans.filter(p=>p.childId===c.id&&!p.date)];for(const p of plans){if(!p?.enabled||!p.care.enabled)continue;const k=p.childId+':'+p.care.teacher+':'+p.care.phone+':'+p.care.room;if(!map.has(k))map.set(k,{p,c});}}if(!map.size)return '';return '<section class="care-directory"><h3>돌봄 선생님 · 교실 연락망</h3><p class="help">'+(useToday?'오늘 ':'선택일 ')+contactDate+'의 연락처를 먼저 표시합니다. 함께 표시된 반복 설정 연락처는 해당 요일을 확인하세요.</p>'+[...map.values()].map(({p,c})=>'<div class="care-directory-row"><div><strong>'+esc(c.name)+' · '+esc(p.care.teacher)+' 선생님</strong><small>'+esc(p.school)+' / '+esc(p.care.room)+' / '+(p.date?p.date:DAYS[p.day]+'요일 설정')+'<br>'+esc(p.care.phone)+'</small></div><div class="inline-buttons">'+schoolCall(p.care.phone)+(p.care.teacherPhone?schoolCall(p.care.teacherPhone,'업무 전화'):'')+'</div></div>').join('')+'</section>';}
function afterRow(a){return '<fieldset class="after-row" data-af-row data-af-id="'+a.id+'"><div class="section-row"><legend>방과후 과목</legend><button type="button" class="text-button" data-action="af-remove">과목 삭제</button></div><div class="form-grid">'+input('af-title','과목 이름',a.title,'text','required maxlength="60"')+input('af-place','수업 교실',a.place,'text','maxlength="120"')+input('af-start','방과후 시작',a.start,'time','required')+input('af-end','방과후 종료',a.end,'time','required')+input('af-teacher','담당 선생님 (선택)',a.teacher,'text','maxlength="50"')+input('af-phone','담당 업무 전화 (선택)',a.phone,'tel','maxlength="30"')+'</div></fieldset>';}
function editSchool(childId,day,date){if(!childId||!childOf(childId)){toast('자녀를 먼저 등록해 주세요.');editChild();return;}day=Number(day);const targetDate=date||selected;const existing=schoolPlanFor(state,childId,targetDate),p=existing||defaultSchool(childId,day);editing={type:'school',id:existing?.id,childId,day,date:targetDate};dialog(childOf(childId).name+' · '+DAYS[day]+'요일 학교생활',formWrap('school','<div class="notice neutral">'+esc(childOf(childId).name)+' · '+DAYS[day]+'요일 ('+targetDate+')<br>돌봄과 방과후가 겹치면 방과후 수업 동안 돌봄을 비운 것으로 나누어 표시합니다.</div>'+select('schoolScope','적용 범위',[['repeat','매주 '+DAYS[day]+'요일'],['date','이 날짜만 변경 / 휴업일']],p.date?'date':'repeat')+'<label class="check-label"><input type="checkbox" name="schoolEnabled" '+(p.enabled?'checked':'')+'>이 날 등교함 (해제하면 등교하지 않는 날)</label><fieldset id="school-fields"><legend>1. 정규수업</legend>'+input('school','학교 이름',p.school,'text','required maxlength="100"')+'<div class="form-grid">'+input('regularStart','정규수업 시작',p.regularStart,'time','required')+input('regularEnd','정규수업 마치는 시간',p.regularEnd,'time','required')+select('schoolMode','등교 이동수단',Object.entries(MODES),p.schoolMode)+input('schoolTravel','등교 이동시간 (분)',p.schoolTravel,'number','required min="0" max="180" step="1"')+'</div><h3 class="form-section-title">2. 방과후 수업</h3><p class="help">이 요일에 듣는 과목을 순서대로 추가하세요. 정규수업 종료 이후여야 합니다.</p><div id="after-rows">'+p.after.map(afterRow).join('')+'</div><button type="button" class="button small" data-action="af-add">+ 방과후 과목 추가</button><h3 class="form-section-title">3. 돌봄교실</h3><label class="check-label"><input type="checkbox" name="careEnabled" '+(p.care.enabled?'checked':'')+'>이 요일에 돌봄교실 이용</label><fieldset id="care-fields"><div class="form-grid">'+input('careStart','돌봄 이용 시작',p.care.start,'time','required')+input('careEnd','돌봄에서 나오는 시간',p.care.end,'time','required')+input('careTeacher','돌봄 선생님 이름 · 필수',p.care.teacher,'text','required maxlength="50"')+input('careRoom','돌봄 교실명 · 필수',p.care.room,'text','required maxlength="120"')+input('carePhone','교실 전화번호 · 필수',p.care.phone,'tel','required maxlength="30" placeholder="학교 공식 연락처"')+input('careTeacherPhone','선생님 업무 전화 (선택)',p.care.teacherPhone,'tel','maxlength="30"')+'</div><label>돌봄 메모 · 내선번호<textarea name="careNote" maxlength="500">'+esc(p.care.note)+'</textarea></label><p class="help">학교에서 안내받은 공식 연락처를 등록하세요. 선생님의 개인 휴대전화번호를 필수로 요구하지 않습니다. 내선번호는 메모에 적어 주세요.</p></fieldset><h3 class="form-section-title">4. 학교 출발 · 인계</h3><div class="form-grid">'+select('pickupMode','학교에서 나오는 방법',Object.entries(MODES),p.pickup.mode)+input('pickupVehicle','차량명 · 동행자',p.pickup.vehicle,'text','maxlength="80"')+input('pickupPlace','탑승 · 인계 장소',p.pickup.place,'text','maxlength="120"')+select('pickupContact','인계 연락처',[['','연결 안 함'],...state.contacts.map(c=>[c.id,c.name])],p.pickup.contactId)+'</div><p class="help">학교 출발 가능시간은 정규수업·방과후·돌봄 중 가장 늦은 종료 시각입니다. 다음 학원의 이동수단·차량명·이동시간은 해당 학원 일정에서도 설정하세요.</p></fieldset><label>학교생활 메모<textarea name="schoolNote" maxlength="500">'+esc(p.note)+'</textarea></label>',!!existing));toggleSchoolFields();}
function toggleSchoolFields(){const f=$('form[data-type="school"]');if(!f)return;const enabled=f.querySelector('[name=schoolEnabled]').checked;$('#school-fields').disabled=!enabled;const care=enabled&&f.querySelector('[name=careEnabled]').checked;$('#care-fields').disabled=!care;$('#care-fields').hidden=!care;}
function submitSchool(form,data){const v=n=>String(data.get(n)||'').trim(),enabled=data.has('schoolEnabled'),once=v('schoolScope')==='date',old=state.schoolPlans.find(p=>p.id===editing.id);const current=defaultSchool(editing.childId,editing.day),p={...current,id:old&&!!old.date===once?old.id:uid(),date:once?editing.date:'',enabled,school:v('school'),regularStart:v('regularStart'),regularEnd:v('regularEnd'),schoolMode:v('schoolMode')||'walk',schoolTravel:Number(v('schoolTravel')||0),after:enabled?[...form.querySelectorAll('[data-af-row]')].map(row=>{const get=n=>row.querySelector('[name='+n+']').value.trim();return {id:row.dataset.afId,title:get('af-title'),start:get('af-start'),end:get('af-end'),place:get('af-place'),teacher:get('af-teacher'),phone:get('af-phone')};}):[],care:{enabled:enabled&&data.has('careEnabled'),start:v('careStart'),end:v('careEnd'),teacher:v('careTeacher'),room:v('careRoom'),phone:v('carePhone'),teacherPhone:v('careTeacherPhone'),note:v('careNote')},pickup:{mode:v('pickupMode')||'walk',vehicle:v('pickupVehicle'),place:v('pickupPlace'),contactId:v('pickupContact')},note:v('schoolNote')};p.after.sort((a,b)=>mins(a.start)-mins(b.start));if(p.id!==old?.id)p.after=p.after.map(a=>({...a,id:uid()}));if(!enabled){p.regularStart='09:00';p.regularEnd='13:00';p.care.enabled=false;}const next=structuredClone(state);next.schoolPlans=next.schoolPlans.filter(x=>!(x.childId===p.childId&&(p.date?x.date===p.date:!x.date&&x.day===p.day))).concat(p);validateState(next);state=next;selected=editing.date;week=monday(selected);feeMonth=selected.slice(0,7);corrupt=false;const ok=save();$('#editor').close();toast(ok?'학교생활을 저장했습니다. 학교 출발시간과 학원 이동 경고를 확인하세요.':'저장 실패: JSON 백업이 필요합니다.');}
async function deleteSchool(){const p=state.schoolPlans.find(p=>p.id===editing.id);if(!p)return;const message=p.date?'이 날짜의 예외 설정을 삭제할까요? 반복 학교생활 설정이 다시 적용됩니다.':'이 요일의 학교생활 설정을 삭제할까요? 기존에 등록한 학교 일정이 다시 표시될 수 있습니다.';if(!await ask(message))return;state.schoolPlans=state.schoolPlans.filter(x=>x.id!==p.id);save();$('#editor').close();toast('학교생활 설정을 삭제했습니다.');}

render();hydrate();setInterval(updateClock,30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)updateClock();});if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});
